<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import AppHeader from './components/AppHeader.vue'
import MatrixPanel from './components/MatrixPanel.vue'
import PreviewPanel from './components/PreviewPanel.vue'
import SettingsPanel from './components/SettingsPanel.vue'
import UploadPanel from './components/UploadPanel.vue'
import { listHistory, removeHistory, resultFromHistory, saveHistory, type HistoryItem } from './services/history'
import type { Config, Matrix, ProcessedResult } from './types'

const config = reactive<Config>({ matrix: { width: 64, height: 64, max_palette_colors: 64, enable_serpentine_layout: false }, options: { fit_mode: 'LETTERBOX', color_mode: 'QUANTIZED_KMEANS', background_color: { r: 0, g: 0, b: 0 }, brightness: 1, contrast: 1, gamma: 1, rotation_deg: 0, flip_horizontal: false, flip_vertical: false } })
const file = ref<File | null>(null); const originalUrl = ref(''); const resultUrl = ref(''); const result = ref<ProcessedResult | null>(null); const matrix = ref<Matrix | null>(null)
const history = ref<HistoryItem[]>([]); const loading = ref(false); const saving = ref(false); const connected = ref(false); const notice = ref(''); const error = ref(''); const dragging = ref(false)
const api = (path: string) => `${import.meta.env.VITE_API_URL || '/api'}${path}`

async function loadConfig() { try { const response = await fetch(api('/config')); if (!response.ok) throw new Error(); Object.assign(config, await response.json()); connected.value = true } catch { error.value = 'Impossible de joindre le backend. Vérifiez que le serveur Rust tourne sur le port 18080.' } }
async function loadHistory() { try { history.value = await listHistory() } catch { error.value = 'Impossible de lire la bibliothèque locale.' } }
async function saveConfig() { saving.value = true; try { const response = await fetch(api('/config'), { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(config) }); if (!response.ok) throw new Error(await response.text()); notice.value = 'Configuration enregistrée' } catch (e) { error.value = e instanceof Error ? e.message : 'Échec de la sauvegarde' } finally { saving.value = false } }
function chooseFile(selected: File | undefined) { if (!selected?.type.startsWith('image/')) { error.value = 'Sélectionnez une image PNG, JPG, GIF ou WebP.'; return } file.value = selected; originalUrl.value = URL.createObjectURL(selected); result.value = null; resultUrl.value = ''; matrix.value = null; notice.value = ''; error.value = '' }
async function processImage() { if (!file.value) return; loading.value = true; try { const data = new FormData(); data.append('image', file.value); const response = await fetch(api('/process'), { method: 'POST', body: data }); if (!response.ok) throw new Error(await response.text()); const type = response.headers.get('content-type') || ''; if (type.includes('image/')) { const blob = await response.blob(); result.value = { animated: false, blob }; resultUrl.value = URL.createObjectURL(blob); await saveHistory({ name: file.value.name, original: file.value, result: blob }) } else { const payload = await response.json(); const frames = (payload.frames || []).map((frame: { png_base64: string; delay_ms: number }) => ({ pngBase64: frame.png_base64, delayMs: frame.delay_ms })); result.value = { animated: true, frames }; await saveHistory({ name: file.value.name, original: file.value, frames }); notice.value = `${frames.length} frames traitées` } await loadHistory() } catch (e) { error.value = e instanceof Error ? e.message : 'Échec du traitement' } finally { loading.value = false } }
async function processMatrix() { if (!file.value) return; loading.value = true; try { const data = new FormData(); data.append('image', file.value); const response = await fetch(`${api('/process')}?return_matrix=true`, { method: 'POST', body: data }); if (!response.ok) throw new Error(await response.text()); const payload = await response.json(); const frame = payload.frames?.[0] || payload; matrix.value = { width: frame.width, height: frame.height, pixels: frame.pixels }; notice.value = 'Matrice générée' } catch (e) { error.value = e instanceof Error ? e.message : 'Impossible de générer la matrice' } finally { loading.value = false } }
function selectHistory(item: HistoryItem | undefined) { if (!item) return; file.value = new File([item.original], item.name, { type: item.original.type }); originalUrl.value = URL.createObjectURL(item.original); result.value = resultFromHistory(item); resultUrl.value = result.value?.blob ? URL.createObjectURL(result.value.blob) : ''; matrix.value = item.matrix || null; notice.value = 'Image restaurée depuis la bibliothèque locale'; error.value = '' }
async function deleteHistory(id: string) { await removeHistory(id); await loadHistory() }
onMounted(() => { loadConfig(); loadHistory() })
</script>
<template><div class="app-shell"><AppHeader :connected="connected" /><main><section class="intro"><div><p class="eyebrow">MATRIX STUDIO / CONFIGURATION</p><h1>Donnez vie à vos pixels.</h1><p class="subtitle">Préparez vos visuels, ajustez le rendu et envoyez-les directement sur votre matrice LED.</p></div><div class="quick-stat"><span>●</span><strong>{{ config.matrix.width }} × {{ config.matrix.height }}</strong><small>RÉSOLUTION ACTIVE</small></div></section><div v-if="error" class="alert error">! {{ error }} <button @click="error = ''">×</button></div><div v-if="notice" class="alert success">✓ {{ notice }}</div><div class="workspace"><UploadPanel :file="file" :original-url="originalUrl" :history="history" :dragging="dragging" @choose="chooseFile" @drop="(event) => { dragging = false; chooseFile(event.dataTransfer?.files[0]) }" @select-history="selectHistory" @remove-history="deleteHistory" /><PreviewPanel :result-url="resultUrl" :result="result" :loading="loading" :has-file="!!file" @process="processImage" @matrix="processMatrix" /></div><SettingsPanel :config="config" :saving="saving" @save="saveConfig" /><MatrixPanel v-if="matrix" :matrix="matrix" /></main><footer><span>PIXELFORGE</span><span>Contrôlez chaque pixel.</span><span>API <code>localhost:18080</code></span></footer></div></template>
<style> @import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');:root{color:#e8e9e3;background:#111310;font-family:'Space Grotesk',sans-serif}*{box-sizing:border-box}body{margin:0;min-width:320px}button,input,select{font:inherit}button{cursor:pointer}.app-shell{min-height:100vh;background:radial-gradient(circle at 75% 0%,#26321d 0,transparent 32rem),#111310}.topbar,main,footer{max-width:1240px;margin:auto}main{padding:66px 24px 80px}.intro{display:flex;justify-content:space-between;align-items:end;margin-bottom:45px}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:.1em;color:#9ab366;margin:0 0 12px}h1{font-size:clamp(36px,5vw,66px);line-height:.98;letter-spacing:-.05em;max-width:620px;margin:0 0 18px}.subtitle{color:#949b8e;max-width:550px;font-size:16px;line-height:1.6}.quick-stat{border-left:1px solid #424a3b;padding-left:25px;min-width:170px}.quick-stat span,.quick-stat strong{color:#c9ef5b}.quick-stat strong{display:block;font-size:22px}.quick-stat small{color:#737d6c;font:10px 'DM Mono',monospace}.workspace{display:grid;grid-template-columns:1fr 1fr;gap:18px}.alert{padding:12px 15px;margin-bottom:18px;font-size:13px}.alert button{float:right;padding:0;background:none;color:inherit;border:0}.error{background:#3b211f;border:1px solid #84453e;color:#ffb3a9}.success{background:#25351b;border:1px solid #59783d;color:#c9ef5b}footer{border-top:1px solid #30352d;padding:22px 24px;display:flex;justify-content:space-between;color:#899184;font:10px 'DM Mono',monospace}footer span:last-child{color:#c9ef5b}@media(max-width:850px){.topbar{padding:0 20px}.intro{display:block}.quick-stat{margin-top:28px}.workspace{grid-template-columns:1fr 1fr}}@media(max-width:560px){main{padding:42px 15px}.workspace{grid-template-columns:1fr}footer{padding:20px 15px;gap:12px;flex-wrap:wrap}}</style>
